function App() {
  return (
    <div className="App">

      <Banner
        title = 'Оформите карту "Сибиряночка"'
        description = 'И получайте бонусы при покупке в магазинах и на сайте'
        imageSrc = '#'
      />

      <SaleBadge

        color="green"
        discount='-50%'
        place='left'
        // icon={<Icon/>}

      />

    </div>
  );
}

export default App;
